BEGIN READ ONLY;
SELECT jsonb_build_object(
'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname),'[]'::jsonb) FROM pg_policies p WHERE schemaname='public' AND tablename IN ('events','event_participants','rounds','matches','match_players','match_results','event_team_sides','event_team_matches')),
'acl',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'grantee',CASE WHEN grantee=0 THEN 'PUBLIC' ELSE grantee::regrole::text END,'grantor',grantor::regrole::text,'privilege',privilege_type,'grantable',is_grantable) ORDER BY c.relname,grantee,privilege_type) FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) WHERE c.oid IN ('public.events'::regclass,'public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass,'public.event_team_sides'::regclass,'public.event_team_matches'::regclass)),
'column_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE x.grantee::regrole::text END,'grantor',x.grantor::regrole::text,'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY c.relname,a.attname,x.grantee,x.privilege_type),'[]'::jsonb) FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE c.oid IN ('public.events'::regclass,'public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass) AND a.attnum>0 AND NOT a.attisdropped),
'rls',(SELECT jsonb_agg(jsonb_build_object('table',relname,'enabled',relrowsecurity,'forced',relforcerowsecurity) ORDER BY relname) FROM pg_class WHERE oid IN ('public.events'::regclass,'public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass,'public.event_team_sides'::regclass,'public.event_team_matches'::regclass)),
'counts',jsonb_build_object('events',(SELECT count(*) FROM public.events),'event_participants',(SELECT count(*) FROM public.event_participants),'rounds',(SELECT count(*) FROM public.rounds),'matches',(SELECT count(*) FROM public.matches),'match_players',(SELECT count(*) FROM public.match_players),'match_results',(SELECT count(*) FROM public.match_results),'event_team_sides',(SELECT count(*) FROM public.event_team_sides),'event_team_matches',(SELECT count(*) FROM public.event_team_matches)),
'privileges',(SELECT jsonb_agg(jsonb_build_object('table',t,'role',r,'privilege',p,'allowed',has_table_privilege(r,'public.'||t,p)) ORDER BY t,r,p) FROM unnest(ARRAY['events','event_participants','rounds','matches','match_players','match_results','event_team_sides','event_team_matches']) tt(t) CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) rr(r) CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE']) pp(p)),
'column_privileges',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'anon_select',has_column_privilege('anon',c.oid,a.attnum,'SELECT'),'auth_select',has_column_privilege('authenticated',c.oid,a.attnum,'SELECT')) ORDER BY c.relname,a.attname) FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid WHERE c.oid IN ('public.events'::regclass,'public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass) AND a.attnum>0 AND NOT a.attisdropped),
'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'def',pg_get_triggerdef(t.oid),'enabled',tgenabled,'function_hash',md5(replace(pg_get_functiondef(p.oid),chr(13),''))) ORDER BY tgrelid::regclass::text,tgname),'[]'::jsonb) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE tgrelid IN ('public.events'::regclass,'public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass,'public.event_team_sides'::regclass,'public.event_team_matches'::regclass) AND NOT tgisinternal),
'functions',(SELECT jsonb_agg(jsonb_build_object('function',p.oid::regprocedure::text,'owner',p.proowner::regrole::text,'bypass',r.rolbypassrls,'super',r.rolsuper,'acl',p.proacl::text,'definer',p.prosecdef,'config',p.proconfig,'hash',md5(replace(pg_get_functiondef(p.oid),chr(13),''))) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_roles r ON r.oid=p.proowner WHERE (n.nspname='public' AND p.proname IN ('can_view_friendly_team_event_by_sides','can_manage_friendly_team_event_by_sides','is_super_user')) OR (n.nspname='profile_link_private' AND p.proname IN ('guard_reference','merge_profiles')) OR n.nspname IN ('events_identity_private','events_operation_private','participants_identity_private','match_identity_private')),
'constraints_hash',(SELECT md5(jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'def',pg_get_constraintdef(oid)) ORDER BY conrelid::regclass::text,conname)::text) FROM pg_constraint WHERE conrelid IN ('public.events'::regclass,'public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass,'public.event_team_sides'::regclass,'public.event_team_matches'::regclass)),
'other_policies_hash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname)::text,'')) FROM pg_policies p WHERE schemaname='public' AND tablename NOT IN ('events','event_participants','rounds','matches','match_players','match_results','event_team_sides','event_team_matches')),
'other_acl_hash',(SELECT md5(jsonb_agg(jsonb_build_object('table',relname,'acl',relacl::text) ORDER BY relname)::text) FROM pg_class WHERE relnamespace='public'::regnamespace AND relkind IN ('r','p','v','m','f') AND oid NOT IN ('public.events'::regclass,'public.event_participants'::regclass,'public.rounds'::regclass,'public.matches'::regclass,'public.match_players'::regclass,'public.match_results'::regclass,'public.event_team_sides'::regclass,'public.event_team_matches'::regclass))
) AS evidence;
COMMIT;
